/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `before_booking_insert` BEFORE INSERT ON `bookings` FOR EACH ROW BEGIN
    DECLARE v_price DECIMAL(10,2);

    SELECT price
    INTO v_price
    FROM packages
    WHERE package_id = NEW.package_id;

    IF v_price IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Invalid package ID';
    END IF;

    IF NEW.number_of_travelers <= 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Number of travelers must be greater than zero';
    END IF;

    SET NEW.total_amount = v_price * NEW.number_of_travelers;
END */;;
DELIMITER ;
