/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `after_booking_update` AFTER UPDATE ON `bookings` FOR EACH ROW BEGIN
    INSERT INTO audit_logs
    (
        user_id,
        action,
        table_name,
        record_id,
        old_data,
        new_data
    )
    VALUES
    (
        NEW.user_id,
        'UPDATE',
        'bookings',
        NEW.booking_id,
        JSON_OBJECT(
            'package_id', OLD.package_id,
            'travelers', OLD.number_of_travelers,
            'total_amount', OLD.total_amount,
            'status', OLD.booking_status
        ),
        JSON_OBJECT(
            'package_id', NEW.package_id,
            'travelers', NEW.number_of_travelers,
            'total_amount', NEW.total_amount,
            'status', NEW.booking_status
        )
    );
END */;;
