CREATE DEFINER=`root`@`localhost` FUNCTION `CalculateDiscount`(
    p_amount DECIMAL(12,2)
) RETURNS decimal(12,2)
    DETERMINISTIC
BEGIN
    DECLARE v_discount DECIMAL(12,2);

    IF p_amount >= 20000 THEN
        SET v_discount = p_amount * 0.10;
    ELSEIF p_amount >= 10000 THEN
        SET v_discount = p_amount * 0.05;
    ELSE
        SET v_discount = 0;
    END IF;

    RETURN v_discount;
END ;;
