CREATE DEFINER=`root`@`localhost` PROCEDURE `CreateBooking`(
    IN p_user_id INT,
    IN p_package_id INT,
    IN p_number_of_travelers INT
)
BEGIN
    DECLARE v_price DECIMAL(10,2);
    DECLARE v_total DECIMAL(12,2);

    SELECT price
    INTO v_price
    FROM packages
    WHERE package_id = p_package_id;

    SET v_total = v_price * p_number_of_travelers;

    INSERT INTO bookings (
        user_id,
        package_id,
        booking_date,
        number_of_travelers,
        total_amount,
        booking_status
    )
    VALUES (
        p_user_id,
        p_package_id,
        CURDATE(),
        p_number_of_travelers,
        v_total,
        'Pending'
    );
END ;;
DELIMITER ;
