CREATE DEFINER=`root`@`localhost` PROCEDURE `GetUserBookings`(IN p_user_id INT)
BEGIN
    SELECT
        b.booking_id,
        u.name AS customer_name,
        p.package_name,
        b.booking_date,
        b.number_of_travelers,
        b.total_amount,
        b.booking_status
    FROM bookings b
    JOIN users u
        ON b.user_id = u.user_id
    JOIN packages p
        ON b.package_id = p.package_id
    WHERE b.user_id = p_user_id;
END ;;
