/*!50003 DROP PROCEDURE IF EXISTS `RunAzuraTests` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = cp850 */ ;
/*!50003 SET character_set_results = cp850 */ ;
/*!50003 SET collation_connection  = cp850_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `RunAzuraTests`()
BEGIN
    DECLARE destination_count INT;
    DECLARE booking_count INT;
    DECLARE invalid_bookings INT;

    SELECT COUNT(*) INTO destination_count
    FROM destinations;

    SELECT COUNT(*) INTO booking_count
    FROM bookings;

    SELECT COUNT(*) INTO invalid_bookings
    FROM bookings b
    LEFT JOIN users u ON b.user_id = u.user_id
    LEFT JOIN packages p ON b.package_id = p.package_id
    WHERE u.user_id IS NULL
       OR p.package_id IS NULL;

    SELECT
        'At least 100 destinations' AS test_name,
        IF(destination_count >= 100, 'PASS', 'FAIL') AS result;

    SELECT
        'At least 1000 bookings' AS test_name,
        IF(booking_count >= 1000, 'PASS', 'FAIL') AS result;

    SELECT
        'No invalid booking references' AS test_name,
        IF(invalid_bookings = 0, 'PASS', 'FAIL') AS result;

    IF destination_count < 100
       OR booking_count < 1000
       OR invalid_bookings > 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'AZURA database tests failed';
    END IF;
END ;;
DELIMITER ;
